    fetch_lines = []
    for i, line in enumerate(lines):
        m = fetch_call_re.search(line)
        if m:
            fetch_lines.append((i, m.group(1), line))
    if len(fetch_lines) < 2:
        continue
    # group into windows of 120 lines, need >=3 fetch calls to be a "dense" handler
    windows = []
    cur = [fetch_lines[0]]
