        if rel.split(os.sep)[0] in EXCLUDE_DIRS:
            dirnames[:] = []
            continue
        for fn in filenames:
            if fn.endswith('.c'):
                yield os.path.join(dirpath, fn)

hits = []
nfiles = 0
for path in iter_files():
